import CitationFormatHero from '@/components/seo/CitationFormatHero'
import { citationFormatPaint, CITATION_FORMAT_CSS, type CitationFormatSlug } from '@/lib/growth/citationFormatHero2411'
import InternalCitationPreview from '@/components/seo/InternalCitationPreview'
import { CITATION_PAGES_RELEASE, isCitationDraftSlug } from '@/lib/growth/citationPagesRelease'
import { BuyerBatch2Lead, BuyerBatch2Details } from '@/components/seo/BuyerQuestions2111'
import { buyerBatch2, buyerBatch2ForIntent } from '@/lib/seo/buyerQuestions2111'
// PROJETO 1 — GOOGLE (docs/PROJETO-1-GOOGLE-2026-09-17.md) — a página de intenção.
//
// Uma rota, 100 páginas (lib/seo/intentPages.ts): "AI video generator for X", "AI Y generator",
// "AI video generator in Z", "W alternative". O que a página tem que os concorrentes não têm:
// filmes REAIS da casa com o selo do motor real (vitrine do fundador), o que a pessoa escreve e o
// que sai, preço e trial lidos da fonte única (nunca literal) e um botão que abre o Studio com o
// prompt daquele nicho já na caixa. Honestidade: nada de "grátis" para motor que o trial não cobre;
// a família 'alternative' fala só da Kineo.
import { BuyerLead2011, BuyerDecision2011 } from '@/components/seo/BuyerDecision2011'
import { BUYER_2011 } from '@/lib/seo/buyerAnswers2011'
import type { Metadata } from 'next'
import Link from 'next/link'
import { notFound } from 'next/navigation'
import Footer from '@/components/Footer'
import { CitationDirectAnswer, CitationDetails } from '@/components/seo/TrafficCitation2310'
import OrganicCtaLink from '@/components/OrganicCtaLink'
import { FREE_FILM_LABEL, getFreeTierOffer, swapFreeTierCopy as ft, trialFilmsForEngine, TRIAL_CREDITS_SHOWN, TRIAL_SEEDANCE15_FILMS } from '@/lib/freeTierOffer'
import { STARTER_MONTH, STARTER_CREDITS, creditsPerReferenceVideo } from '@/lib/marketingPrice'
import { PUBLIC_ENGINE_EXAMPLES } from '@/lib/publicExamples'
import { getDraftCitationIntentPage, getIntentPage, INTENT_FAMILY_LABEL, INTENT_HUB_PATH, INTENT_PAGES, INTENT_SLUGS, intentPagePath, type IntentEngine } from '@/lib/seo/intentPages'
import { PaginaClaraCards, PaginaClaraTopo, PaginaClaraVitrine } from '@/components/seo/PaginaClara' // KINEO-PAGINAS-IA-CLARAS-2110 — o menu do topo, os 4 cards e a vitrine atual da home
import { PAGINA_CLARA_CLASSE, PAGINA_CLARA_FUNDO } from '@/lib/seo/paginasIaClaras2110' // KINEO-PAGINAS-IA-CLARAS-2110
import { STORY_VIDEO_COPY, STORY_VIDEO_ENGINE, STORY_VIDEO_UPDATED } from '@/lib/growth/storyVideoPage'
import H3TurboDetails from '@/components/H3TurboDetails'

const OFFER = getFreeTierOffer()
const BASE = 'https://www.usekineo.com'
import { STANDARD_FILM_NAME } from '@/lib/seo/citacoesRotina1711'
const ENGINE_NAME: Record<IntentEngine, string> = { fast: 'Kineo 1', cinematic_ai: 'Seedance 1.5' }
// Only the three unpublished d09 formats adopt the current standard-film label. Historical examples stay intact.
const DRAWING_INTENTS_2311 = new Set(['cartoon-videos', 'animated-story-videos', 'animal-story-videos'])

// Published routes are enumerated at build time. Private previews are rewritten to a separate server route.
export const dynamic = 'force-static'
export const dynamicParams = false

export function generateStaticParams() {
  return INTENT_SLUGS.map((slug) => ({ slug }))
}

export function generateMetadata({ params }: { params: { slug: string } }): Metadata {
  const p = getIntentPage(params.slug)
  if (!p) return isCitationDraftSlug(params.slug) ? { robots: { index: false, follow: false } } : {}
  const url = `${BASE}${intentPagePath(p.slug)}`
  const description = p.slug === 'story-videos' ? STORY_VIDEO_COPY.description : `${p.intro.slice(0, 150).replace(/\s+\S*$/, '')}… Real films, ${p.slug === 'urdu' || buyerBatch2ForIntent(p.slug) || DRAWING_INTENTS_2311.has(p.slug) ? STANDARD_FILM_NAME : ENGINE_NAME[p.engine]} and generative engines, free trial with no card.`
  return {
    metadataBase: new URL(BASE),
    title: p.title,
    description,
    alternates: { canonical: url },
    openGraph: { title: p.title, description, url, type: 'website' },
    twitter: { card: 'summary_large_image', title: p.title, description },
  }
}

/** Studio já com o prompt do nicho na caixa; cadastro preserva o destino (mesmo padrão das páginas por motor). */
function studioHref(slug: string, prompt: string, engine: IntentEngine, language?: string): string {
  const campaign = `intent_${slug}`.slice(0, 100)
  // Revisão da E2b (texto, achado 1): SEM duração cravada. Com duration=60 o "Make this film free" abria um Seedance de
  // 60 s (25 cr) para o trial de 10 — não era grátis. Sem ?duration, o Studio escolhe a maior duração que o saldo paga
  // (lib/growth/entradaSeedance15 duracaoDeEntrada): o trial abre no filme grátis de 15 s.
  // e o motor viaja no vocabulário do Studio (cinematic_ai não é chave de lá e era ignorado em silêncio).
  const studio = new URLSearchParams({ engine: engine === 'cinematic_ai' ? 'seedance' : engine, prompt, script_mode: 'ai', intent_campaign: campaign })
  if (language) studio.set('language', language) // KINEO-IDIOMAS-15: a página de idioma abre o Studio já na língua
  // KINEO-ORIGEM-HONESTA-2026-09-23 — SEM utm_source/utm_medium cravados. O link
  // dizia `utm_source=google` para todo mundo, e quem chegava do ChatGPT (ou de
  // qualquer outro lugar) e se cadastrava por aqui virava 'google' em
  // profiles.signup_utm_source. Conferido em lib/analytics.ts (captureSourceOnce):
  // first-touch grava utm_* quando existem e, sem utm, grava `referrer` =
  // sanitizeAcquisitionReferrer(document.referrer) — o referrer EXTERNO do
  // pouso (chatgpt.com, google.com); um pouso sem utm e sem referrer não grava
  // nada, para que um pouso externo posterior ainda vença. E em
  // lib/acquisitionSource.ts (acquisitionSource): utm explícito vence; sem utm,
  // a origem sai do host do referrer (sourceFromHost). Portanto, sem utm_source
  // aqui, a origem registrada é a REAL. utm_campaign e intent_campaign ficam:
  // são a página, não a origem.
  const signup = new URLSearchParams({ utm_campaign: campaign, intent_campaign: campaign, redirect: `/studio?${studio.toString()}` })
  return `/signup?${signup.toString()}`
}

const CARD = { background: '#FFFFFF', border: '1px solid #E4E4E0', borderRadius: 16 } as const

export default function IntentPage(props: { params: { slug: string } }) {
  if (isCitationDraftSlug(props.params.slug)) {
    if (CITATION_PAGES_RELEASE === 'off') notFound()
    if (CITATION_PAGES_RELEASE === 'internal') return <InternalCitationPreview>{IntentPageContent(props)}</InternalCitationPreview>
  }
  return IntentPageContent(props)
}

function IntentPageContent({ params }: { params: { slug: string } }) {
  const p = getIntentPage(params.slug) ?? getDraftCitationIntentPage(params.slug)
  if (!p) notFound()
  const url = `${BASE}${intentPagePath(p.slug)}`
  const engineCost = creditsPerReferenceVideo(p.engine)
  const story = p.slug === 'story-videos'
  const batchPage = buyerBatch2ForIntent(params.slug)
  const offerName = story ? STORY_VIDEO_ENGINE : p.slug === 'urdu' || batchPage || DRAWING_INTENTS_2311.has(p.slug) ? STANDARD_FILM_NAME : ENGINE_NAME[p.engine]
  // KINEO-FILME-GRATIS-15S-2026-09-29 — o Kineo 1 ('fast') não é mais oferecido a conta nova: a página não diz que o trial
  // cobre filmes dele (era "the trial covers 2 Kineo 1 films"). O que o trial paga é o Seedance 1.5 de 15 s.
  const trialFilms = p.engine === 'fast' ? 0 : trialFilmsForEngine(engineCost)
  const trialFreeFilm = TRIAL_SEEDANCE15_FILMS >= 1 ? `; a new account's trial pays for one ${FREE_FILM_LABEL} instead` : ''
  // A vitrine é `as const`: nem toda entrada tem poster/preview leve. O Kineo 1 da home é um master de 48 MB;
  // aqui vai o preview de 5 s (arenaPreviewPath) quando existir. Nunca a URL do fal.
  const films = PUBLIC_ENGINE_EXAMPLES.filter((e) => e.engine === p.engine).slice(0, 3).map((e) => {
    const x = e as { id: string; title: string; videoPath: string; posterPath?: string; arenaPreviewPath?: string; arenaPosterPath?: string }
    return { id: x.id, title: x.title, videoPath: x.arenaPreviewPath ?? x.videoPath, posterPath: x.arenaPosterPath ?? x.posterPath }
  })
  const cta = studioHref(p.slug, p.examplePrompt, p.engine, p.language)
  const campaign = `intent_${p.slug}`
  const formatHero = DRAWING_INTENTS_2311.has(p.slug)
  const tint = (value: string) => formatHero ? citationFormatPaint(value) : value
  const card = formatHero ? { background: tint('#FFFFFF'), border: tint('1px solid #E4E4E0'), borderRadius: 16 } : CARD
  const siblings = INTENT_PAGES.filter((x) => x.family === p.family && x.slug !== p.slug).slice(0, 8)
  const sourcePageFaqs = p.slug === 'urdu' ? [...p.faq, { q: BUYER_2011.urdu.q, a: BUYER_2011.urdu.answer }] : p.faq
  const pageFaqs = batchPage || DRAWING_INTENTS_2311.has(p.slug) ? sourcePageFaqs.map(f => ({ ...f, a: f.a.replaceAll('Seedance 1.5', STANDARD_FILM_NAME) })) : sourcePageFaqs
  const originalFaqs = story
    ? [...STORY_VIDEO_COPY.faq, { q: 'Which model creates the story scenes?', a: STORY_VIDEO_COPY.engineAnswer }, { q: 'How much does it cost?', a: STORY_VIDEO_COPY.costAnswer }]
    : [...pageFaqs, { q: 'How much does it cost?', a: `The free trial gives ${TRIAL_CREDITS_SHOWN} credits with no card. ${p.slug === 'urdu' || batchPage || DRAWING_INTENTS_2311.has(p.slug) ? STANDARD_FILM_NAME : ENGINE_NAME[p.engine]} costs ${engineCost} credits for a 60-second film${trialFilms > 0 ? `, so the trial covers ${trialFilms} film${trialFilms > 1 ? 's' : ''}` : `, which needs a plan${trialFreeFilm}`}. Plans start at ${STARTER_MONTH} for ${STARTER_CREDITS} credits.` }]
  const originalVisibleFaqs = story ? originalFaqs : [...pageFaqs, { q: 'How much does it cost?', a: `The free trial gives ${TRIAL_CREDITS_SHOWN} credits with no card. ${p.slug === 'urdu' || batchPage || DRAWING_INTENTS_2311.has(p.slug) ? STANDARD_FILM_NAME : ENGINE_NAME[p.engine]} costs ${engineCost} credits per 60-second film${trialFilms > 0 ? `, so the trial covers ${trialFilms} film${trialFilms > 1 ? 's' : ''}` : `, which needs a plan${trialFreeFilm}`}. Plans start at ${STARTER_MONTH} for ${STARTER_CREDITS} credits.` }]

  const batchFaqs = batchPage ? buyerBatch2(batchPage).faqs : []
  const faqs = [...batchFaqs, ...originalFaqs]
  const visibleFaqs = [...batchFaqs, ...originalVisibleFaqs]
  const faqJsonLd = {
    '@context': 'https://schema.org',
    '@type': 'FAQPage',
    mainEntity: faqs.map((f) => ({ '@type': 'Question', name: f.q, acceptedAnswer: { '@type': 'Answer', text: f.a } })),
  }
  const breadcrumbJsonLd = {
    '@context': 'https://schema.org',
    '@type': 'BreadcrumbList',
    itemListElement: [
      { '@type': 'ListItem', position: 1, name: 'Kineo', item: `${BASE}/` },
      { '@type': 'ListItem', position: 2, name: 'AI video generator', item: `${BASE}/ai-video-generator` },
      { '@type': 'ListItem', position: 3, name: INTENT_FAMILY_LABEL[p.family], item: `${BASE}${INTENT_HUB_PATH}` },
      { '@type': 'ListItem', position: 4, name: p.h1, item: url },
    ],
  }
  const videoJsonLd = films.map((f) => ({
    '@context': 'https://schema.org',
    '@type': 'VideoObject',
    name: f.title,
    description: `A short film made with Kineo on ${ENGINE_NAME[p.engine]}: ${f.title}.`,
    thumbnailUrl: f.posterPath ? `${BASE}${f.posterPath}` : undefined,
    contentUrl: f.videoPath.startsWith('http') ? f.videoPath : `${BASE}${f.videoPath}`,
    uploadDate: '2026-09-07',
  }))

  return (
    <main className={formatHero ? PAGINA_CLARA_CLASSE + ' kpl-citation-format-2411' : PAGINA_CLARA_CLASSE} style={{ minHeight: '100vh', background: formatHero ? 'var(--cfh-bg)' : PAGINA_CLARA_FUNDO, color: tint('#0E1116'), fontFamily: 'var(--font-sans), Arial, sans-serif' }}>
      <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(faqJsonLd).replace(/</g, '\\u003c') }} />
      <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(breadcrumbJsonLd).replace(/</g, '\\u003c') }} />
      <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(videoJsonLd).replace(/</g, '\\u003c') }} />
      <PaginaClaraTopo />{formatHero && <style data-citation-format-theme="2411" dangerouslySetInnerHTML={{ __html: CITATION_FORMAT_CSS }} />}{/* KINEO-PAGINAS-IA-CLARAS-2110 */}

      <div style={{ maxWidth: 960, margin: '0 auto', padding: '28px 18px 64px' }}>
        <nav aria-label="Breadcrumb" style={{ color: tint('#5A5F67'), fontSize: 13 }}>
          <Link href="/" style={{ color: tint('#0A5CFF'), fontWeight: 800, textDecoration: 'none' }}>Kineo</Link>
          <span aria-hidden> / </span>
          <Link href="/ai-video-generator" style={{ color: tint('#0A5CFF'), textDecoration: 'none' }}>AI video generator</Link>
          <span aria-hidden> / </span>
          <Link href={INTENT_HUB_PATH} style={{ color: tint('#0A5CFF'), textDecoration: 'none' }}>{INTENT_FAMILY_LABEL[p.family]}</Link>
        </nav>

        <section style={{ marginTop: 30, textAlign: 'center' }}>
          <div style={{ display: 'inline-block', fontSize: '0.72rem', fontWeight: 800, letterSpacing: '0.06em', textTransform: 'uppercase', color: tint('#0A5CFF'), background: tint('#E8EFFF'), border: '1px solid rgba(10,92,255,0.35)', borderRadius: 980, padding: '6px 12px' }}>
            {offerName} · {engineCost} credits per 60-second film
          </div>
          <h1 style={{ fontSize: 'clamp(1.8rem, 5vw, 2.6rem)', fontWeight: 650, lineHeight: 1.15, margin: '16px 0 0' }}>{p.h1}</h1>
          {batchPage && <BuyerBatch2Lead page={batchPage} />}
          {params.slug === 'urdu' && <BuyerLead2011 kind="urdu" />}
          {params.slug === 'urdu' ? <CitationDirectAnswer page="urdu" /> : <p style={{ fontSize: '1.02rem', color: tint('#5A5F67'), lineHeight: 1.6, margin: '16px auto 0', maxWidth: 680 }}>{story ? STORY_VIDEO_COPY.intro : p.intro}</p>}
          {params.slug === 'urdu' && <BuyerDecision2011 kind="urdu" />}
          {formatHero && <CitationFormatHero slug={p.slug as CitationFormatSlug} examplePrompt={p.examplePrompt} />}
          <PaginaClaraCards />{/* KINEO-PAGINAS-IA-CLARAS-2110 — os 4 cards da home logo abaixo do título e da 1ª frase (a resposta citável continua sendo o 1º parágrafo depois do H1) */}
          <div style={{ display: 'flex', flexWrap: 'wrap', justifyContent: 'center', gap: 10, marginTop: 22 }}>
            <OrganicCtaLink href={cta} source={campaign} placement="hero" style={{ display: 'inline-block', background: tint('#0A5CFF'), color: formatHero ? 'var(--kpl-on-accent, #fff)' : '#fff', fontWeight: 750, padding: '15px 32px', borderRadius: 980, textDecoration: 'none', fontSize: '1.05rem' }}>
              {story ? 'Prepare this story →' : 'Make this film free →'}
            </OrganicCtaLink>
            <Link href="/pricing" style={{ display: 'inline-block', border: tint('1px solid #D2D2CD'), color: tint('#0E1116'), fontWeight: 800, padding: '14px 24px', borderRadius: 980, textDecoration: 'none' }}>
              See plans &amp; credits
            </Link>
          </div>
          <p style={{ fontSize: '0.82rem', color: tint('#5A5F67'), margin: '12px 0 0' }}>
            {story ? 'Review the prepared story, selected model, duration and credit cost in Studio before generating.' : <>
              {ft(OFFER, `${TRIAL_CREDITS_SHOWN} free credits, no card`, OFFER.copy.chip)}
              {trialFilms > 0 ? ` · the trial covers ${trialFilms} ${p.slug === 'urdu' || batchPage || DRAWING_INTENTS_2311.has(p.slug) ? STANDARD_FILM_NAME : ENGINE_NAME[p.engine]} film${trialFilms > 1 ? 's' : ''}` : `${TRIAL_SEEDANCE15_FILMS >= 1 ? ` · the trial pays for one ${FREE_FILM_LABEL}` : ''} · 60-second films on a plan (from ${STARTER_MONTH})`}
            </>}
          </p>
        </section>

        {/* O que a pessoa escreve → o que sai */}
        <section style={{ marginTop: 44, display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', gap: 14 }}>
          <div style={{ ...card, padding: 18 }}>
            <div style={{ fontSize: '0.72rem', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.06em', color: tint('#5A5F67') }}>What you write</div>
            <p style={{ margin: '10px 0 0', fontSize: '1rem', lineHeight: 1.55, color: tint('#0E1116') }}>“{p.examplePrompt}”</p>
            <p style={{ margin: '10px 0 0', fontSize: '0.82rem', color: tint('#5A5F67') }}>One idea is enough. A full script is narrated word for word.</p>
          </div>
          <div style={{ ...card, padding: 18 }}>
            <div style={{ fontSize: '0.72rem', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.06em', color: tint('#5A5F67') }}>What you get</div>
            <ul style={{ margin: '10px 0 0', paddingLeft: 18, lineHeight: 1.7, color: tint('#2A2F37'), fontSize: '0.95rem' }}>
              <li>A hook-first script and a natural AI voice</li>
              <li>{story ? 'AI-generated scenes planned around the narration' : <>A scene for every line, {p.engine === 'fast' ? 'from real footage and generated stills' : 'generated from the text'}</>}</li>
              <li>Captions timed to the voice, music, a vertical MP4</li>
              <li>{story ? 'Review the story, narration and character continuity before publishing' : 'A written next episode, so it becomes a series'}</li>
            </ul>
            <p style={{ margin: '10px 0 0', fontSize: '0.82rem', color: tint('#5A5F67') }}>{p.engineWhy}</p>
          </div>
        </section>

        {story && <H3TurboDetails reviewedOn={STORY_VIDEO_UPDATED} heading={`${offerName} cost per finished story`} />}

        {p.competitor && (
          <section style={{ marginTop: 36, ...card, padding: 18 }}>
            <h2 style={{ fontSize: '1.15rem', fontWeight: 650, margin: 0 }}>What Kineo does differently</h2>
            <ul style={{ margin: '10px 0 0', paddingLeft: 18, lineHeight: 1.7, color: tint('#2A2F37'), fontSize: '0.95rem' }}>
              {p.competitor.differences.map((d, i) => <li key={i}>{d}</li>)}
            </ul>
            <p style={{ margin: '10px 0 0', fontSize: '0.8rem', color: tint('#5A5F67') }}>We describe Kineo only. {p.competitor.name}'s features and prices are theirs to state and change.</p>
          </section>
        )}

        {/* KINEO-PAGINAS-IA-CLARAS-2110 — a galeria velha (3 filmes da casa deste motor) saiu da tela; entra a vitrine atual (a mesma da /claude-connector).
            O VideoObject do JSON-LD segue como estava (regra: JSON-LD intocado) — ver docs/PAGINAS-IA-CLARAS-2026-10-21.md. */}
        {batchPage && <BuyerBatch2Details page={batchPage} />}
        <PaginaClaraVitrine />
        {params.slug === 'urdu' ? <CitationDetails page="urdu" /> : null}

        {/* FAQ */}
        <section style={{ marginTop: 44 }}>
          <h2 style={{ fontSize: '1.3rem', fontWeight: 650, margin: '0 0 12px' }}>Questions</h2>
          {visibleFaqs.map((f) => (
            <details key={f.q} style={{ ...card, padding: '12px 16px', marginBottom: 8 }}>
              <summary style={{ cursor: 'pointer', fontWeight: 800 }}>{f.q}</summary>
              <p style={{ margin: '8px 0 0', color: tint('#2A2F37'), lineHeight: 1.6 }}>{f.a}</p>
            </details>
          ))}
        </section>

        {/* Irmãs: o caminho de rastreio interno */}
        {siblings.length > 0 && (
          <section style={{ marginTop: 40 }}>
            <h2 style={{ fontSize: '1rem', fontWeight: 650, color: tint('#5A5F67'), margin: '0 0 10px' }}>More · {INTENT_FAMILY_LABEL[p.family]}</h2>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
              {siblings.map((s) => (
                <Link key={s.slug} href={intentPagePath(s.slug)} style={{ fontSize: '0.85rem', color: tint('#0A5CFF'), textDecoration: 'none', border: tint('1px solid #E4E4E0'), borderRadius: 980, padding: '6px 12px' }}>{s.h1}</Link>
              ))}
              <Link href={INTENT_HUB_PATH} style={{ fontSize: '0.85rem', color: tint('#0E1116'), textDecoration: 'none', border: tint('1px solid #D2D2CD'), borderRadius: 980, padding: '6px 12px' }}>All use cases →</Link>
            </div>
          </section>
        )}

        <section style={{ marginTop: 44, textAlign: 'center' }}>
          <OrganicCtaLink href={cta} source={campaign} placement="footer" style={{ display: 'inline-block', background: tint('#0A5CFF'), color: formatHero ? 'var(--kpl-on-accent, #fff)' : '#fff', fontWeight: 750, padding: '15px 32px', borderRadius: 980, textDecoration: 'none', fontSize: '1.05rem' }}>
            {story ? 'Prepare this story →' : 'Make this film free →'}
          </OrganicCtaLink>
        </section>
      </div>
      <Footer showStats={false} />
    </main>
  )
}

